#include <list>
#include <iostream>

int main() {
    std::list<int> l = {10, 20, 30};
    auto it = l.begin();
    ++it; // Points to 20

    // O(1) insertion, preserving 'it'
    l.insert(it, 15); 

    // 'it' still points to 20 (now the 3rd element)
    std::cout << "Iterator still points to: " << *it << "\n";

    // O(1) deletion via iterator
    it = l.erase(it); // 'it' now points to 30

    std::cout << "Iterator after erase points to: " << *it << "\n";
}
